<?php $from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$sales=one("SELECT COALESCE(SUM(total),0) n FROM ventas WHERE estado='COMPLETADA' AND DATE(fecha) BETWEEN ? AND ?",[$from,$to])['n'];$profit=one("SELECT COALESCE(SUM((d.precio_unitario-d.costo_unitario)*d.cantidad),0) n FROM detalle_ventas d JOIN ventas v ON v.id_venta=d.id_venta WHERE v.estado='COMPLETADA' AND DATE(v.fecha) BETWEEN ? AND ?",[$from,$to])['n'];$top=allrows("SELECT p.nombre,SUM(d.cantidad) cantidad,SUM(d.subtotal) total FROM detalle_ventas d JOIN ventas v ON v.id_venta=d.id_venta JOIN productos p ON p.id_producto=d.id_producto WHERE v.estado='COMPLETADA' AND DATE(v.fecha) BETWEEN ? AND ? GROUP BY p.id_producto ORDER BY cantidad DESC LIMIT 10",[$from,$to]);?>
<section class="panel"><form class="filter"><label>Desde<input type="date" name="from" value="<?=e($from)?>"></label><label>Hasta<input type="date" name="to" value="<?=e($to)?>"></label><input type="hidden" name="page" value="reports"><button class="btn primary">Consultar</button></form><div class="stats"><div class="card"><small>Ventas</small><b><?=money($sales)?></b></div><div class="card"><small>Ganancia</small><b><?=money($profit)?></b></div></div></section>
<section class="panel"><h2>Productos más vendidos</h2><table><tr><th>Producto</th><th>Cantidad</th><th>Ventas</th></tr><?php foreach($top as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=$r['cantidad']?></td><td><?=money($r['total'])?></td></tr><?php endforeach;?></table></section>
